command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
Set-Location -LiteralPath $repo
& git fetch origin main work/test-infra-simplify-20261005 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "cleanup fetch failed"}
& git diff --quiet 37d1e1a2e22252c2f06cdb9909d7c7315e4837f0 f5b3fc72894f2545063a634283c6c714414a2ecf --
if($LASTEXITCODE -ne 0){throw "refuse branch cleanup: merged main tree differs from work branch tree"}
& git push origin --delete work/test-infra-simplify-20261005
if($LASTEXITCODE -ne 0){throw "failed to delete merged work branch"}
Write-Host "MERGED_WORK_BRANCH_DELETED=PASS"
